abstract class Shape {
    abstract double area(); // to be implemented differently by each shape
}

class Circle extends Shape {
    private double radius;
    Circle(double radius) { this.radius = radius; }

    @Override
    double area() {
        return Math.PI * radius * radius;
    }
}

class Square extends Shape {
    private double side;
    Square(double side) { this.side = side; }

    @Override
    double area() {
        return side * side;
    }
}

class Calculator {
    // Overloading: same name "add", different parameter types (compile-time polymorphism)
    int add(int a, int b) {
        return a + b;
    }

    double add(double a, double b) {
        return a + b;
    }
}

public class Main {
    public static void main(String[] args) {
        // Runtime polymorphism: the SAME call, shape.area(), behaves differently per object
        Shape[] shapes = { new Circle(5), new Square(4) };
        for (Shape shape : shapes) {
            System.out.println("Area: " + shape.area());
        }

        // Compile-time polymorphism: the compiler picks which add() to call by argument type
        Calculator calc = new Calculator();
        System.out.println("Int sum: " + calc.add(2, 3));
        System.out.println("Double sum: " + calc.add(2.5, 3.5));
    }
}

