from abc import ABC, abstractmethod
import math


class Shape(ABC):
    @abstractmethod
    def area(self):
        pass  # to be implemented differently by each shape


class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

    def area(self):
        return math.pi * self.radius * self.radius


class Square(Shape):
    def __init__(self, side):
        self.side = side

    def area(self):
        return self.side * self.side


class Calculator:
    # Python has no true method overloading, one add() naturally handles any numeric type
    def add(self, a, b):
        return a + b


if __name__ == "__main__":
    # Runtime polymorphism: the SAME call, shape.area(), behaves differently per object
    shapes = [Circle(5), Square(4)]
    for shape in shapes:
        print("Area:", shape.area())

    # Python's dynamic typing means one add() already works for both ints and floats
    calc = Calculator()
    print("Int sum:", calc.add(2, 3))
    print("Double sum:", calc.add(2.5, 3.5))

