#include <iostream>
#include <cmath>
using namespace std;

class Shape {
public:
    virtual double area() = 0; // to be implemented differently by each shape
    virtual ~Shape() {}
};

class Circle : public Shape {
private:
    double radius;
public:
    Circle(double radius) : radius(radius) {}
    double area() override {
        return M_PI * radius * radius;
    }
};

class Square : public Shape {
private:
    double side;
public:
    Square(double side) : side(side) {}
    double area() override {
        return side * side;
    }
};

class Calculator {
public:
    // Overloading: same name "add", different parameter types (compile-time polymorphism)
    int add(int a, int b) {
        return a + b;
    }
    double add(double a, double b) {
        return a + b;
    }
};

int main() {
    // Runtime polymorphism: the SAME call, shape->area(), behaves differently per object
    Shape* shapes[] = { new Circle(5), new Square(4) };
    for (Shape* shape : shapes) {
        cout << "Area: " << shape->area() << endl;
    }

    // Compile-time polymorphism: the compiler picks which add() to call by argument type
    Calculator calc;
    cout << "Int sum: " << calc.add(2, 3) << endl;
    cout << "Double sum: " << calc.add(2.5, 3.5) << endl;

    delete shapes[0];
    delete shapes[1];
    return 0;
}
